/* Finance is isolated from all pre-existing Life Hub storage. */
'use strict';
const esc=escapeHtml;
const FIN_KEY='akb-finance-v1',F=Finance;
function finRenderIncome(){
 const sources=F.incomeSources(finState),today=finToday(),upcoming=F.upcomingPaydays(finState,today);
 const select=document.getElementById('fin-pay-source'),selected=select.value;
 select.innerHTML=sources.filter(s=>s.active).map(s=>`<option value="${esc(s.id)}">${esc(s.name)}</option>`).join('')||'<option value="">Add an income source first</option>';
 if(sources.some(s=>s.active&&s.id===selected))select.value=selected;
 document.getElementById('fin-income-sources').innerHTML=sources.map(s=>{const next=s.active?F.upcomingPaydays({...finState,incomeSources:[s]},today,1)[0]?.date:null;return `<div class="fin-row"><div><strong>${esc(s.name)}</strong><p class="fin-note">${s.active?(next?'Next: '+next:'No future date · edit when known'):'Paused'}${s.expected?' · expected '+finMoney(s.expected):''}</p></div><div class="fin-actions"><button type="button" class="btn btn-ghost" data-fin="schedule" data-id="${esc(s.id)}">Edit</button><button type="button" class="btn btn-ghost" data-fin="income-toggle" data-id="${esc(s.id)}">${s.active?'Pause':'Resume'}</button></div></div>`;}).join('');
 document.getElementById('fin-upcoming-income').innerHTML=upcoming.map(p=>`<div class="fin-row"><span>${esc(p.name)}<br><small>${p.date}</small></span><span>${p.calendarEstimate?.net!=null?finMoney(p.expected)+' · calendar estimate':p.expected?finMoney(p.expected)+' · expected':'Actual amount when paid'}</span></div>`).join('')||'<p class="fin-note">No future household payday is scheduled.</p>';
 document.getElementById('fin-pay-schedule').textContent=upcoming[0]?'Next household payday: '+upcoming[0].date:'Add your pay, partner pay, business income and benefits separately.';
 const add=document.querySelector('[data-fin="schedule"]:not([data-id])');add.textContent=sources.length?'Add income source':'Set payday schedule';
}
let finTemplateReviewed=null;
async function finTemplatePreview(){
 const asOf=document.getElementById('fin-template-date').value;if(asOf>finToday())throw Error('Balance date cannot be future-dated');
 const data=FinanceTemplate.prepare(finSheets,asOf,document.getElementById('fin-visa').value);
 const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(JSON.stringify(data)));
 const hash=Array.from(new Uint8Array(digest),n=>n.toString(16).padStart(2,'0')).join('');
 finTemplateReviewed={data,hash};
 document.getElementById('fin-template-preview').innerHTML=`<h3>Review accounts & budget</h3><div class="fin-scroll"><table><thead><tr><th>Account</th><th>Opening balance</th><th>Rate</th><th>Monthly payment</th></tr></thead><tbody>${data.debts.map(d=>`<tr><td>${esc(d.name)}</td><td>${finMoney(d.opening)}</td><td>${d.apr.toFixed(2)}%</td><td>${finMoney(d.payment)}</td></tr>`).join('')}</tbody></table></div><p class="fin-note">${data.bills.length} funded budget allocations · ${finMoney(data.bills.reduce((n,b)=>n+b.amount,0))} monthly living costs, savings and obligations. Mortgage and other debt payments are reserved separately.</p><div class="fin-scroll">${data.bills.map(b=>`<div class="fin-row"><span>${esc(b.name)}</span><span>${finMoney(b.amount)}</span></div>`).join('')}</div><p class="fin-note">Visa starts at $0. Existing debt balances and history are retained. New rates apply from today. This workbook has no exact lender due dates: the 1st and 16th are planning assumptions. The old forecast is not imported as payment history. Debt priority: ${data.strategy}. Missing categories are retained on reimport; set obsolete category amounts to 0 in Budget to retire them.</p><button class="btn btn-primary" data-fin="template-apply">Apply complete budget</button>`;
}
function finTemplateApply(){if(!finTemplateReviewed)throw Error('Preview the complete budget first');const {data,hash}=finTemplateReviewed;let next=F.merge(finState,data.debts,'debt',hash+'-debts',finToday());next=F.merge(next,data.bills,'budget',hash+'-budget');next.baselineIncome=data.baselineIncome;next.strategy=finState.imports.length?finState.strategy:data.strategy;finCommit(next);document.getElementById('fin-import').innerHTML='';finTemplateReviewed=null;}
let finStoredRaw=null;
let finState,finBlocked=false,finSheets=[],finImportRows=[],finImportKind='',finImportHash='',finPlan=null;
function finToday(){const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');}
function finMoney(n){return new Intl.NumberFormat('en-CA',{style:'currency',currency:'CAD'}).format(n/100);}
function finId(){return crypto.randomUUID();}
function finMessage(message,error=false){const el=document.getElementById('fin-status');el.textContent=message;el.setAttribute('role',error?'alert':'status');}
function finLoad(){try{const raw=localStorage.getItem(FIN_KEY);finStoredRaw=raw;finState=raw?F.validate(JSON.parse(raw)):F.empty();if(finState.debts.some(d=>d.asOf>finToday())||finState.goals?.some(g=>g.asOf>finToday()))throw Error('Future opening balance');}catch(e){finState=F.empty();finBlocked=true;}}
function finCommit(next){F.validate(next);if(next.calendarPay?.refreshedOn>finToday())throw Error('Calendar snapshot cannot be future-dated');if(next.debts.some(d=>d.asOf>finToday())||next.events.some(e=>e.date>finToday())||next.paydays.some(p=>p.date>finToday())||next.debts.some(d=>d.deadlineAsOf&&d.deadlineAsOf>finToday())||(next.cfoReview&&next.cfoReview.date>finToday())||(next.decisionPlan&&next.decisionPlan.asOf>finToday())||next.decisions?.some(x=>x.reviewedOn>finToday())||next.paydays.some(p=>p.revisions?.some(r=>r.date>finToday()))||next.goals?.some(x=>x.asOf>finToday())||next.goalEvents?.some(x=>x.date>finToday())||next.payUses?.some(x=>x.date>finToday()||(x.releasedOn&&x.releasedOn>finToday())||(x.reversedOn&&x.reversedOn>finToday())||(x.paidOn&&x.paidOn>finToday())))throw Error('Actual balances and history cannot be future-dated');if(finBlocked)throw Error('Stored Finance data could not be read. Export the raw backup before restoring.');if(localStorage.getItem(FIN_KEY)!==finStoredRaw)throw Error('Finance changed in another tab. Reload before saving; no changes were applied.');const serialized=JSON.stringify(next);try{localStorage.setItem(FIN_KEY,serialized);}catch(e){throw Error('Unable to save on this device. No changes were applied. Export a backup and free browser storage.');}finStoredRaw=serialized;finState=next;finPlan=null;finRender();finMessage('Saved on this device.');}
function finField(name,label,type='text',value='',extra=''){return `<label for="fin-${name}">${label}</label><input class="inp" id="fin-${name}" name="${name}" type="${type}" value="${esc(String(value))}" ${extra}>`;}
function finFrequency(value='monthly'){return `<label for="fin-frequency">Frequency</label><select class="inp" id="fin-frequency" name="frequency">${['monthly','weekly','biweekly'].map(f=>`<option ${f===value?'selected':''}>${f}</option>`).join('')}</select>`;}
function finRender(){const today=finToday(),currentProjection=finState.decisionPlan?FinanceScenarios.simulate(finState,F.currentPlan(finState,today),today):null;let total=0;const debts=finState.debts.map(d=>{const b=F.balance(d,finState.events,today),forecast=currentProjection?{date:currentProjection.debts.find(x=>x.id===d.id)?.date,reason:'No payoff forecast with current plan'}:F.forecast(d,finState.events,today,finState.payUses);total+=b.amount;const progress=d.opening?Math.max(0,Math.min(100,(1-b.amount/d.opening)*100)):b.amount?0:100;return `<article class="card"><div class="fin-row"><h2>${esc(d.name)}</h2><span class="fin-badge">${d.apr.toFixed(2)}% APR</span></div><div class="fin-total">${finMoney(b.amount)}</div><p class="fin-note">Projected balance · ${today}<br>${b.confirmed?`Lender-confirmed ${finMoney(b.confirmed.amount)} on ${b.confirmed.date}`:`Opening estimate ${finMoney(d.opening)} on ${d.asOf} · not lender-confirmed`}</p><progress max="100" value="${progress}" aria-label="${esc(d.name)} payoff progress"></progress><p class="fin-note">${Math.round(progress)}% below opening balance · ${finMoney(b.interest)} estimated interest since opening<br>${finMoney(d.payment)} ${d.frequency}${d.installments?' total · split-month payments':''} · schedule starts ${d.nextDue}<br>Projected payoff: ${forecast.date||esc(forecast.reason)}</p>${F.debtDeadlines(d,finState.events,today).length?`<details><summary>Payoff milestones</summary>${F.debtDeadlines(d,finState.events,today).map(x=>`<div class="fin-row"><span>${esc(x.label)}<br><small>Pay off by ${x.due}</small></span><strong>${finMoney(x.remaining)}</strong></div>`).join('')}<p class="fin-note">Estimated portions of this account, not additional debts. Confirm lender allocation.</p></details>`:''}<div class="fin-actions"><button class="btn btn-ghost" data-fin="payment" data-id="${esc(d.id)}">Record payment</button><button class="btn btn-ghost" data-fin="reconcile" data-id="${esc(d.id)}">Reconcile</button><button class="btn btn-ghost" data-fin="edit" data-id="${esc(d.id)}">Payment settings</button><button class="btn btn-ghost" data-fin="deadlines" data-id="${esc(d.id)}">Payoff dates & milestones</button></div></article>`;}).join('');
 const target=F.focusTarget(finState,today),nextGoal=(finState.goals||[]).filter(g=>F.goalBalance(finState,g.id,today)<g.target).sort((a,b)=>(a.deadline||'9999').localeCompare(b.deadline||'9999'))[0],nextIncome=F.upcomingPaydays(finState,today,1)[0];
 const choice=`<details class="fin-focus-settings"><summary>Choose your focus</summary><label for="fin-focus-choice">Next target</label><select class="inp" id="fin-focus-choice"><option value="">Automatic · deadlines, then ${finState.strategy==='snowball'?'smallest balance':'highest interest'} first</option>${finState.debts.filter(d=>F.balance(d,finState.events,today).amount>0).map(d=>`<option value="${esc(d.id)}" ${d.id===finState.focusDebtId?'selected':''}>${esc(d.name)}</option>`).join('')}</select><p class="fin-note">Dated milestones take priority in both the focus and extra-pay allocations. After those, payday allocations follow your debt priority: ${finState.strategy==='snowball'?'smallest balance':'highest interest'} first. Once a pinned debt is paid, the next active debt appears automatically.</p><button class="btn btn-ghost" data-fin="strategy">Switch debt priority</button></details>`;
 let focus;
 if(target){
  const {debt:d,amount,confirmed,milestone}=target,pace=milestone?F.deadlinePace(finState,milestone,today):null,forecast=currentProjection?{date:currentProjection.debts.find(x=>x.id===d.id)?.date,reason:'No payoff forecast with current plan'}:F.forecast(d,finState.events,today,finState.payUses),progress=milestone?Math.max(0,Math.min(100,(1-milestone.remaining/milestone.amount)*100)):d.opening?Math.max(0,Math.min(100,(1-amount/d.opening)*100)):0;
  const next=F.duePayments(d,today,F.add(today,370)).map(x=>({...x,remaining:Math.max(0,x.amount-F.scheduledPaid(finState,d.id,x.date,today))})).find(x=>x.remaining>0);
  let recommendation=null;try{recommendation=F.debtRecommendation(finState,d.id,today);}catch{}
  focus=`<article class="card fin-focus" id="fin-next-focus"><span class="fin-badge">Next focus · ${milestone?'deadline first':d.id===finState.focusDebtId?'pinned':'automatic'}</span><h2>${milestone?'Clear '+esc(milestone.label)+' · '+esc(d.name):'Pay off '+esc(d.name)}</h2><div class="fin-total">${finMoney(milestone?.remaining??amount)}</div><p class="fin-note">${milestone?'Estimated milestone remaining':'Projected remaining'} · ${today}</p><progress max="100" value="${progress}" aria-label="Next target payoff progress"></progress><div class="fin-focus-facts"><div><span>${milestone?'Full account balance':'Progress'}</span><strong>${milestone?finMoney(amount):Math.round(progress)+'% below opening'}</strong></div><div><span>${milestone?'Payoff deadline':'Projected goal date'}</span><strong>${milestone?finDisplayDate(milestone.due):forecast.date?finDisplayDate(forecast.date):'Set a workable payment'}</strong></div></div>${milestone?`<p class="fin-note ${pace.overdue?'fin-danger':''}">${pace.overdue?'Deadline has passed — confirm lender terms.':`Plan ${finMoney(pace.amount)} per household payday · ${pace.paydays} pay dates including today.`}</p>`:''}<div class="fin-impact" id="fin-target-payment"><span>Recommended toward this account</span>${recommendation?`<strong class="fin-total">${finMoney(recommendation.amount)}</strong><p class="fin-note">From unassigned actual household pay received ${finDisplayDate(recommendation.start)} · includes ${finMoney(recommendation.extra)} in extra debt payments. Living costs, required payments and dated priorities are protected first.${recommendation.amount===0?' This account has no funded allocation left in this pay period. Review This paycheque for the current priorities.':''}</p>`:'<p class="fin-note">Enter actual take-home pay to calculate your extra debt payment. The recurring payment is not your payoff target.</p>'}<button class="btn btn-ghost" data-fin="paycheck-new">${recommendation?'Enter another paycheque':'Enter actual pay for a recommendation'}</button></div><button class="btn btn-primary" data-fin="payment" data-id="${esc(d.id)}">Record payment toward this target</button><button class="btn btn-ghost" data-fin="decision-jump">Check a financial decision</button><details class="fin-plan-settings"><summary>Plan details & settings</summary><p class="fin-note">${next?`Recurring payment on file: ${finMoney(Math.min(amount,next.remaining))} · ${finDisplayDate(next.date)}. Extra debt allocations are recommended above from actual pay.`:"No recurring payment set."}</p><p class="fin-note">${confirmed?`Account lender-confirmed ${finMoney(confirmed.amount)} on ${confirmed.date}`:`Opening estimate ${finMoney(d.opening)} on ${d.asOf} · not lender-confirmed`}<br>${d.apr.toFixed(2)}% APR · full-account ${currentProjection?'saved-plan':'scheduled'} payoff estimate: ${forecast.date?finDisplayDate(forecast.date):esc(forecast.reason)}.</p><p class="fin-note">${milestone?'This dated portion is protected before general extra debt payments. The payday pace includes scheduled payments, not an additional charge. It is a planning estimate, not a guarantee; allow lender processing time and confirm payment allocation and deferred-interest terms. '+(F.incomeSources(finState).some(x=>x.active)?'':'Add income schedules to spread the target across future paydays.'):(currentProjection?'Goal date uses your saved monthly extra-money plan. Review assumptions when your budget changes.':'Goal date assumes scheduled payments only. Extra payments can bring it forward.')}</p><div class="fin-actions"><button class="btn btn-ghost" data-fin="reconcile" data-id="${esc(d.id)}">Confirm lender balance</button><button class="btn btn-ghost" data-fin="edit" data-id="${esc(d.id)}">Payment settings</button><button class="btn btn-ghost" data-fin="deadlines" data-id="${esc(d.id)}">Payoff dates & milestones</button></div>${choice}</details></article>`;

 }else if(nextGoal){const saved=F.goalBalance(finState,nextGoal.id,today);focus=`<article class="card fin-focus" id="fin-next-focus"><span class="fin-badge">Next focus · real savings goal</span><h2>Fund ${esc(nextGoal.name)}</h2><div class="fin-total">${finMoney(nextGoal.target-saved)}</div><p class="fin-note">Remaining to reach this goal · ${today}</p><progress max="100" value="${Math.min(100,saved/nextGoal.target*100)}" aria-label="Next goal funding progress"></progress><p class="fin-note">${finMoney(saved)} recorded saved / ${finMoney(nextGoal.target)} target${nextGoal.deadline?' · desired date '+nextGoal.deadline:''}. Recorded contributions and goal balance confirmations update this progress.</p><button class="btn btn-primary" data-fin="goal-assign" data-id="${esc(nextGoal.id)}">Record a contribution from a paycheque</button><button class="btn btn-ghost" data-fin="decision-jump">Check a financial decision</button></article>`;}else focus=`<article class="card fin-focus" id="fin-next-focus"><span class="fin-badge">Next focus</span><h2>${finState.debts.length?'Your tracked debts are paid off':'Build your next money milestone'}</h2><p class="fin-note">${finState.debts.length?'All projected debt balances are $0. Confirm your lender statements, then explore a savings goal in What If.':'Import your budget workbook or add a debt to see your next focus here. New Visa accounts always start at $0.'}</p>${finState.debts.length?'':'<div class="fin-actions"><button class="btn btn-primary" data-fin="open-import">Import budget workbook</button><button class="btn btn-ghost" data-fin="add">Add a debt</button></div>'}</article>`;
 const overviewOpen=document.getElementById('fin-debt-overview')?.open;
 document.getElementById('fin-dashboard').innerHTML=focus+`<p class="fin-note fin-next-income">${nextIncome?'Next household payday: '+esc(nextIncome.name)+' · '+finDisplayDate(nextIncome.date):'Set up your household pay schedules below.'}</p><details class="card" id="fin-debt-overview" ${overviewOpen?'open':''}><summary>All debts & total · ${finState.debts.length} accounts</summary><div class="fin-total">${finMoney(total)}</div><p class="fin-note">Total projected debt as of ${today}</p>${debts}<div class="fin-actions"><button class="btn btn-ghost" data-fin="add">Add debt</button></div></details>`;

 document.getElementById('fin-budget').innerHTML=finState.bills.map(b=>`<div class="fin-row"><div><strong>${esc(b.name)}</strong><p class="fin-note">${finMoney(b.amount)} ${b.frequency} · starts ${b.nextDue}</p></div><button class="btn btn-ghost" data-fin="bill-edit" data-id="${esc(b.id)}">Edit</button></div>`).join('')||'<p class="fin-note">Add living costs and upcoming obligations here. Enter each expense once; debt payments are reserved separately.</p>';
 document.getElementById('fin-history').innerHTML=[...finState.events.map(e=>({...e,name:finState.debts.find(d=>d.id===e.debtId)?.name})),...finState.paydays.map(p=>({...p,type:'take-home pay',name:p.sourceName||F.incomeSources(finState).find(x=>x.id===p.sourceId)?.name||'Household pay'}))].sort((a,b)=>b.date.localeCompare(a.date)).map(e=>`<div class="fin-row"><div><strong>${esc(e.name)}</strong><p class="fin-note">${e.date} · ${e.voided?'corrected payment (excluded)':e.type==='reconcile'?'lender reconciliation':esc(e.type)}</p></div><span>${finMoney(e.amount)}</span></div>`).join('')||'<p class="fin-note">Completed payments, reconciliations and actual pay will appear here.</p>';
 document.querySelector('[data-fin=strategy]')?.setAttribute('aria-label','Switch debt priority, current: '+(finState.strategy||'avalanche'));finRenderIncome();
 document.getElementById('fin-plan').innerHTML='';
 if(typeof finProgressChart==='function')finProgressChart();if(typeof finCalendarRender==='function')finCalendarRender();if(typeof finPaycheckRender==='function')finPaycheckRender();if(typeof finDecisionRender==='function')finDecisionRender();finRenderCfo();if(typeof finScenarioRender==='function')finScenarioRender();if(finState.baselineIncome)document.getElementById('fin-pay-schedule').textContent+=' · Workbook monthly income plan: '+finMoney(finState.baselineIncome.reduce((n,p)=>n+p.amount,0));if(finBlocked)finMessage('Existing Finance data is unreadable. Saving is disabled to protect it. Download the raw backup, then restore a valid Finance backup.',true);
}
function finScheduleFields(source){
 const mode=source?.mode==='interval'?(source.days===7?'weekly':source.days===14?'biweekly':'interval'):source?.mode||'biweekly';
 const options=(values,value)=>values.map(([v,label])=>`<option value="${v}" ${String(v)===String(value)?'selected':''}>${label}</option>`).join('');
 const dayOptions=Array.from({length:31},(_,i)=>[i+1,String(i+1)]).concat([[0,'Last day']]);
 return finField('name','1. Whose income is this?','text',source?.name||(!F.incomeSources(finState).length?'Household pay':''),'required maxlength="100" placeholder="My pay, Kyra’s pay, Business, CCB…"')+
 `<label for="fin-mode">2. How often are you paid?</label><select class="inp" id="fin-mode" name="mode">${options([['weekly','Every week'],['biweekly','Every two weeks'],['semimonthly','Twice a month'],['monthly','Once a month · calendar date'],['monthlyweekday','Once a month · weekday rule'],['monthbusiness','Business days before month end'],['interval','Every N days'],['once','Irregular · one planned date']],mode)}</select>`+
 finField('anchor','3. Known payday / schedule starts','date',source?.anchor||finToday(),'required')+
 `<div data-pay-rule="interval">${finField('days','Days between paydays','number',source?.days||14,'min="1" max="366" step="1"')}</div>`+
 `<div data-pay-rule="monthly"><label for="fin-monthDay">Day of the month</label><select class="inp" id="fin-monthDay" name="monthDay">${options(dayOptions,source?.monthDay??Number((source?.anchor||finToday()).slice(8)))}</select></div>`+
 `<div data-pay-rule="semimonthly" class="fin-grid"><div><label for="fin-day1">First pay date</label><select class="inp" id="fin-day1" name="day1">${options(dayOptions,source?.monthDays?.[0]??1)}</select></div><div><label for="fin-day2">Second pay date</label><select class="inp" id="fin-day2" name="day2">${options(dayOptions,source?.monthDays?.[1]??16)}</select></div></div>`+
 `<div data-pay-rule="monthlyweekday" class="fin-grid"><div><label for="fin-ordinal">Which week?</label><select class="inp" id="fin-ordinal" name="ordinal">${options([[1,'First'],[2,'Second'],[3,'Third'],[4,'Fourth'],[-1,'Last']],source?.ordinal??-1)}</select></div><div><label for="fin-weekday">Weekday</label><select class="inp" id="fin-weekday" name="weekday">${options(['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'].map((x,i)=>[i,x]),source?.weekday??5)}</select></div></div>`+
 `<div data-pay-rule="monthbusiness">${finField('businessCount','Business day counting back from month end · 1 = last, 3 = third last','number',source?.businessCount||3,'min="1" max="20" step="1"')}<p class="fin-note">Counts Monday–Friday, excluding your listed holiday / non-pay dates.</p></div>`+
 `<p class="fin-note">Weekly and every-two-week schedules follow the weekday of your known payday. Dates such as the 31st use the last day of shorter months. Irregular income is a single expected date; add a new date when known.</p>`+
 `<label for="fin-adjustment">4. If payday falls on a weekend or a listed non-pay date</label><select class="inp" id="fin-adjustment" name="adjustment">${options([['none','Keep the date'],['earlier','Move to the previous available weekday'],['later','Move to the next available weekday']],source?.adjustment||'none')}</select>`+
 `<details><summary>Holiday dates & individual changes</summary><p class="fin-note">Add your payer’s holiday / bank closure dates. No holiday calendar is assumed. These dates and weekend handling use the rule above. A specific date move takes precedence, including weekends.</p><div id="fin-holiday-dates">${(source?.holidays||[]).concat(['']).map(on=>finHolidayRow(on)).join('')}</div><button type="button" class="btn btn-ghost" data-fin="schedule-date" data-kind="holiday">Add non-pay date</button><p class="fin-note">Move one scheduled payday without changing its repeating rule. Clear both fields to remove a move.</p><div id="fin-date-overrides">${(source?.overrides||[]).concat([{scheduled:'',actual:''}]).map(x=>finOverrideRow(x)).join('')}</div><button type="button" class="btn btn-ghost" data-fin="schedule-date" data-kind="override">Add date move</button></details>`+
 finField('expected','5. Expected take-home amount · optional','number',source?.expected?source.expected/100:'','min="0" step="0.01" inputmode="decimal"')+
 `<p class="fin-note">Expected income is a preview. Your payday plan only uses actual pay you confirm.</p>`;
}
function finHolidayRow(on){return `<label>Non-pay date<input class="inp" type="date" name="holiday" value="${esc(on)}"></label>`;}
function finOverrideRow(x){return `<div class="fin-grid fin-date-move"><label>Scheduled date<input class="inp" type="date" name="scheduled" value="${esc(x.scheduled)}"></label><label>Pay on instead<input class="inp" type="date" name="actual" value="${esc(x.actual)}"></label></div>`;}
function finScheduleValues(form,id){
 const data=new FormData(form),v=Object.fromEntries(data),mode=['weekly','biweekly'].includes(v.mode)?'interval':v.mode;
 const row={id:id||'preview',name:v.name.trim(),anchor:v.anchor,days:v.mode==='weekly'?7:v.mode==='biweekly'?14:Number(v.days||14),mode,expected:v.expected?F.money(v.expected):0,active:true,adjustment:v.adjustment,holidays:[...new Set(data.getAll('holiday').filter(Boolean))],overrides:[]};
 const scheduled=data.getAll('scheduled'),actual=data.getAll('actual');for(let i=0;i<scheduled.length;i++){if(!!scheduled[i]!==!!actual[i])throw Error('Fill both dates for each date move');if(scheduled[i])row.overrides.push({scheduled:scheduled[i],actual:actual[i]});}
 if(mode==='monthbusiness')row.businessCount=Number(v.businessCount);
 if(mode==='monthly')row.monthDay=Number(v.monthDay);
 if(mode==='semimonthly')row.monthDays=[Number(v.day1),Number(v.day2)];
 if(mode==='monthlyweekday'){row.ordinal=Number(v.ordinal);row.weekday=Number(v.weekday);}
 F.validate({...F.empty(),incomeSources:[{...row,name:row.name||'Preview'}]});return row;
}
function finSchedulePreview(){
 const form=document.querySelector('#fin-edit-form[data-action="schedule"]');if(!form)return;
 const mode=form.elements.mode.value;form.querySelectorAll('[data-pay-rule]').forEach(el=>{el.hidden=el.dataset.payRule!==mode;for(const input of el.querySelectorAll('input,select'))input.disabled=el.hidden;});
 const host=document.getElementById('fin-schedule-preview');try{const source=finScheduleValues(form,form.dataset.id),upcoming=F.upcomingPaydays({...F.empty(),incomeSources:[source]},finToday(),6);host.innerHTML='<h3>Check your next paydays</h3>'+(upcoming.length?upcoming.map(p=>`<div class="fin-row"><span>${finDisplayDate(p.date)}</span><span>${p.expected?finMoney(p.expected):'Confirm amount on payday'}</span></div>`).join(''):'<p class="fin-note">No future paydays. Choose a future date for this source.</p>');}catch(e){host.textContent=e.message;}
}
function finDisplayDate(on){return new Intl.DateTimeFormat('en-CA',{weekday:'short',month:'short',day:'numeric',year:'numeric',timeZone:'UTC'}).format(new Date(on+'T00:00:00Z'));}

function finDeadlineRow(x={}){return `<div class="fin-deadline-row"><label>Milestone name<input class="inp" name="milestoneLabel" value="${esc(x.label||'')}" maxlength="100" placeholder="Promotion or agreed payoff"></label><div class="fin-grid"><label>Remaining amount<input class="inp" type="number" name="milestoneAmount" min="0" step="0.01" inputmode="decimal" value="${x.remaining===undefined?'':x.remaining/100}"></label><label>Pay off by<input class="inp" type="date" name="milestoneDue" value="${esc(x.due||'')}"></label></div></div>`;}
function finSaveDeadlines(form,next,id){
 const data=new FormData(form),labels=data.getAll('milestoneLabel'),amounts=data.getAll('milestoneAmount'),dates=data.getAll('milestoneDue'),d=next.debts.find(x=>x.id===id),today=finToday(),items=[];
 for(let i=0;i<labels.length;i++){if(!labels[i]&&!amounts[i]&&!dates[i])continue;if(!labels[i].trim()||!amounts[i]||!dates[i])throw Error('Complete the name, remaining amount and date for each milestone, or clear all three to remove it');const amount=F.money(amounts[i]);if(amount)items.push({id:finId(),label:labels[i].trim(),amount,due:dates[i]});}
 if(items.reduce((n,x)=>n+x.amount,0)>F.balance(d,next.events,today).amount)throw Error('Milestones are portions of this debt. Their total cannot exceed its projected balance; reconcile the account first if needed.');
 d.deadlines=items;d.deadlineAsOf=today;d.deadlinePaymentIds=next.events.filter(e=>e.debtId===id&&e.type==='payment'&&!e.voided).map(e=>e.id);
}

function finEditor(action,id){const d=finState.debts.find(d=>d.id===id),b=finState.bills.find(b=>b.id===id),today=finToday();let title='',fields='';
 if(action==='deadlines'){title='Payoff dates & milestones';fields=`<p class="fin-note">${esc(d.name)} · projected account balance ${finMoney(F.balance(d,finState.events,today).amount)}. Add promotion expiry dates or agreed payoff dates. For multiple promotions, enter the remaining amount of each part. These are portions of the account, never extra debts.</p><p class="fin-note">Future recorded payments reduce these milestones in earliest-deadline order as an estimate. Check the lender’s actual payment allocation and update remaining amounts after statements. Reconciliations cap milestones to the account balance but cannot confirm which promotion was paid. Clear a row or set it to $0 to retire it.</p><div id="fin-deadline-rows">${F.debtDeadlines(d,finState.events,today).map(finDeadlineRow).join('')}${finDeadlineRow()}</div><button type="button" class="btn btn-ghost" data-fin="deadline-row">Add another milestone</button>`;}
 if(action==='payment'||action==='reconcile'){title=action==='payment'?'Record completed payment':'Reconcile lender statement';fields=`<p class="fin-note">${esc(d.name)} · ${action==='reconcile'?'This sets a confirmed balance at the end of the statement date, after payments on that date. Later payments remain in history.':'Record only payments actually made. Recommendations do not create payments.'}</p>`+finField('amount',action==='payment'?'Amount paid':'Lender balance','number','','required min="0" step="0.01" inputmode="decimal"')+finField('date',action==='payment'?'Payment date':'Statement date','date',today,`required min="${d.asOf}" max="${today}"`);}
 if(action==='payment'){const pays=finState.paydays.filter(p=>F.paycheckRemaining(finState,p.id)>0),preferred=pays.find(p=>p.id===finSelectedPayId)||pays[pays.length-1];if(pays.length)fields+=`<label for="fin-payment-pay">Funded by paycheque</label><select class="inp" id="fin-payment-pay" name="payId"><option value="">Outside a tracked paycheque / link later</option>${pays.map(p=>`<option value="${esc(p.id)}" ${p.id===preferred?.id?'selected':''}>${esc(p.sourceName||'Household pay')} · ${p.date} · ${finMoney(F.paycheckRemaining(finState,p.id))} unassigned</option>`).join('')}</select><label for="fin-payment-due">Scheduled due date this funds · optional</label><input class="inp" id="fin-payment-due" name="due" type="date" value="${F.duePayments(d,today,F.add(today,32)).find(x=>x.amount>F.scheduledPaid(finState,d.id,x.date,today))?.date||''}"><p class="fin-note">A tracked paycheque records this payment once and updates its unassigned amount. Clear the due date for a general extra payment.</p>`;}
 if(action==='add'||action==='edit'){title=d?'Payment settings':'Add debt';fields=(d?.installments?'<p class="fin-note">This debt has split-month payments. Saving here replaces them with the single recurring schedule below.</p>':'')+(d?'':finField('name','Account name','text','','required maxlength="100"')+finField('opening','Opening balance · Visa will start at $0','number','','required min="0" step="0.01"')+finField('asOf','Opening balance date','date',today,`required max="${today}"`))+finField('apr','Annual interest rate (%)','number',d?.apr??'','required min="0" max="100" step="0.001"')+finField('payment','Scheduled payment','number',d?d.payment/100:'','required min="0" step="0.01"')+finFrequency(d?.frequency)+finField('nextDue','Schedule anchor / first due date','date',d?.nextDue||today,'required');}
 if(action==='bill'||action==='bill-edit'){title=b?'Edit budget category':'Add budget category';fields=finField('name','Category or obligation','text',b?.name||'','required maxlength="100"')+finField('amount','Amount per occurrence','number',b?b.amount/100:'','required min="0" step="0.01"')+finFrequency(b?.frequency)+finField('nextDue','Schedule anchor / first due date','date',b?.nextDue||today,'required');}
 if(action==='schedule'){const source=F.incomeSources(finState).find(x=>x.id===id);title=source?'Edit income source':'Set up an income source';fields=finScheduleFields(source);}

 document.getElementById('fin-editor').innerHTML=`<form class="card" id="fin-edit-form" data-action="${action}" data-id="${esc(id||'')}"><h2>${title}</h2>${fields}<button class="btn btn-primary" type="submit">Save ${action==='payment'?'payment':action==='reconcile'?'confirmed balance':'settings'}</button><button type="button" class="btn btn-ghost" data-fin="cancel">Cancel</button>${action==='schedule'?'<div id="fin-schedule-preview" class="fin-preview" aria-live="polite"></div>':''}</form>`;document.getElementById('fin-editor').scrollIntoView({block:'start',behavior:'smooth'});document.querySelector('#fin-edit-form input')?.focus();if(action==='schedule')finSchedulePreview();
}
function finSaveEditor(form){const v=Object.fromEntries(new FormData(form)),action=form.dataset.action,id=form.dataset.id,today=finToday();let next=structuredClone(finState);
 if(action==='payment'||action==='reconcile'){if(v.date>today)throw Error('Completed events cannot be future-dated');if(action==='payment')next=v.payId?F.recordPayUse(next,{id:finId(),payId:v.payId,kind:'debt',targetId:id,amount:F.money(v.amount),date:v.date,note:'',...(v.due?{due:v.due}:{})}):F.payment(next,id,F.money(v.amount),v.date,finId());else {const d=next.debts.find(d=>d.id===id);if(v.date<d.asOf)throw Error('Statement predates opening balance');if(next.events.some(e=>e.type==='reconcile'&&e.debtId===id&&e.date===v.date))throw Error('A reconciliation already exists on this date');next.events.push({id:finId(),debtId:id,type:'reconcile',amount:F.money(v.amount),date:v.date});next.events.sort((a,b)=>a.date.localeCompare(b.date)||(a.type==='payment'?-1:1));}}
 if(action==='add'||action==='edit'){const settings={apr:Number(v.apr),payment:F.money(v.payment),frequency:v.frequency,nextDue:v.nextDue};if(action==='edit'){const account=next.debts.find(d=>d.id===id);account.initialApr=account.initialApr??account.apr;if(account.apr!==settings.apr)account.rates=[...(account.rates||[]),{date:today,apr:settings.apr}];delete account.installments;Object.assign(account,settings);}else{if(next.debts.some(d=>F.key(d.name)===F.key(v.name)))throw Error('Account already exists');if(v.asOf>today)throw Error('Opening date cannot be in the future');next.debts.push({id:finId(),name:v.name.trim(),opening:/\bvisa\b/i.test(v.name)?0:F.money(v.opening),asOf:v.asOf,...settings});}}
 if(action==='bill'||action==='bill-edit'){const row={id:id||finId(),name:v.name.trim(),amount:F.money(v.amount),frequency:v.frequency,nextDue:v.nextDue};if(!row.name)throw Error('Enter a category name');if(action==='bill-edit')Object.assign(next.bills.find(b=>b.id===id),row);else{if(next.bills.some(b=>F.key(b.name)===F.key(row.name)))throw Error('Category already exists');next.bills.push(row);}}
 if(action==='deadlines')finSaveDeadlines(form,next,id);
 if(action==='schedule'){const sources=F.incomeSources(next).map(x=>({...x}));if(sources.some(x=>x.id!==id&&F.key(x.name)===F.key(v.name)))throw Error('An income source with this name already exists');const row=finScheduleValues(form,id||finId());row.active=sources.find(x=>x.id===id)?.active??true;const i=sources.findIndex(x=>x.id===id);if(i<0)sources.push(row);else sources[i]=row;next.incomeSources=sources;}
 finCommit(next);document.getElementById('fin-editor').innerHTML='';
}
async function finPickWorkbook(file){if(!file)return;finSheets=[];finImportRows=[];window.finReviewed=null;finTemplateReviewed=null;document.getElementById('fin-import').innerHTML='';finMessage('Reading workbook privately on this device…');finSheets=await FinanceXlsx.read(await file.arrayBuffer());if(!finSheets.length)throw Error('No worksheets found');document.getElementById('fin-import').innerHTML=`${FinanceTemplate.detect(finSheets)?`<div class="card"><h3>Split-month budget detected</h3><p class="fin-note">Import the Balance Sheet budget and Action Plan accounts together. Mortgage becomes a debt and is excluded from living costs. First-half obligations are reserved on the 1st; second-half on the 16th. Review actual due dates afterward.</p>${finField('template-date','Current balance date','date',finToday(),`required max="${finToday()}"`)}<label for="fin-visa">Which account is Visa?</label><select class="inp" id="fin-visa"><option value="">Choose account</option>${finSheets.find(s=>s.name==='Action Plan').rows.slice(13,23).filter(r=>r[1]).map(r=>`<option>${esc(String(r[1]))}</option>`).join('')}<option value="separate">Separate Visa account</option></select><button class="btn btn-primary" data-fin="template-preview">Preview complete budget</button><div id="fin-template-preview"></div></div>`:''}<label for="fin-sheet">Worksheet</label><select class="inp" id="fin-sheet">${finSheets.map((s,i)=>`<option value="${i}">${esc(s.name)}</option>`).join('')}</select><label for="fin-header">Header row (1-based)</label><input class="inp" type="number" min="1" value="1" id="fin-header"><label for="fin-kind">Import as</label><select class="inp" id="fin-kind"><option value="debt">Debts</option><option value="budget">Budget categories / obligations</option></select><button class="btn btn-primary" data-fin="map">Choose columns</button><div id="fin-mapping"></div><div id="fin-preview"></div>`;finMessage('Choose the worksheet and header row. Import debts and budget categories separately.');}
function finMap(){window.finReviewed=null;const sheet=finSheets[Number(document.getElementById('fin-sheet').value)],header=Number(document.getElementById('fin-header').value)-1;if(!Number.isInteger(header)||header<0||header>=sheet.rows.length)throw Error('Choose an existing header row');const headers=sheet.rows[header];finImportRows=sheet.rows.slice(header+1);finImportKind=document.getElementById('fin-kind').value;const fields=finImportKind==='debt'?[['name','Account name'],['balance','Balance'],['apr','Interest rate'],['payment','Scheduled payment'],['frequency','Frequency (optional)'],['nextDue','First due date (optional)']]:[['name','Category'],['amount','Amount per occurrence'],['frequency','Frequency (optional)'],['nextDue','First due date (optional)']];document.getElementById('fin-mapping').innerHTML=`<p class="fin-note">Use a table containing only individual accounts/categories, excluding total rows. Empty names are skipped. Dates must be YYYY-MM-DD or Excel date numbers. Unmapped frequency defaults to monthly; due date defaults to the snapshot date. Formula cells require cached values saved by Excel.</p>${fields.map(([k,label])=>`<label for="fin-map-${k}">${label}</label><select class="inp" id="fin-map-${k}" data-map="${k}"><option value="">Choose column${['frequency','nextDue'].includes(k)?' (optional)':''}</option>${Array.from(headers,(h,i)=>`<option value="${i}">${i+1}: ${esc(String(h||'(blank)'))}</option>`).join('')}</select>`).join('')}${finField('snapshot','Balance / budget snapshot date','date',finToday(),`required max="${finToday()}"`)}${finImportKind==='debt'?'<label><input type="checkbox" id="fin-fraction"> Interest rates are decimal fractions (0.1999 means 19.99%)</label>':''}<button class="btn btn-primary" data-fin="preview">Preview import</button>`;document.getElementById('fin-preview').innerHTML='';}
function finMappedRows(){const map={};document.querySelectorAll('[data-map]').forEach(el=>{map[el.dataset.map]=el.value===''?undefined:Number(el.value);});const required=finImportKind==='debt'?['name','balance','apr','payment']:['name','amount'];if(required.some(k=>map[k]===undefined))throw Error('Map all required columns');map.fractionRate=!!document.getElementById('fin-fraction')?.checked;const rows=finImportRows.map(r=>{const copy=[...r];if(map.nextDue!==undefined&&/^\d+(\.\d+)?$/.test(String(copy[map.nextDue]||''))){copy[map.nextDue]=F.add('1899-12-30',Math.floor(Number(copy[map.nextDue])));}return copy;});const asOf=document.getElementById('fin-snapshot').value;if(asOf>finToday())throw Error('Snapshot date cannot be in the future');return F.importRows(rows,map,finImportKind,asOf);}
async function finPreview(){const rows=finMappedRows();if(!rows.length)throw Error('No rows to import');const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(JSON.stringify({kind:finImportKind,rows})));finImportHash=Array.from(new Uint8Array(digest),n=>n.toString(16).padStart(2,'0')).join('');const source=finImportKind==='debt'?finState.debts:finState.bills;document.getElementById('fin-preview').innerHTML=`<h3>Review ${rows.length} rows</h3><div class="fin-scroll"><table><thead><tr><th>Name</th><th>Amount</th><th>Action</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.name)}</td><td>${finMoney(r.opening??r.amount)}</td><td>${source.some(d=>F.key(d.name)===F.key(r.name))?'Update settings; retain balance/history':'Add new'}</td></tr>`).join('')}</tbody></table></div><p class="fin-note">Visa starts at $0 for new accounts. Existing debt opening balances, payments and reconciliations are retained. Updated spreadsheet balances are never added as transactions. Interest rate changes apply from today, preserving earlier rates. Import only changed/new entries; removed spreadsheet categories remain until you set their budget amount to 0. Use Reconcile to confirm a new statement balance. Match accounts by the same name on future imports.</p><button class="btn btn-primary" data-fin="apply">Apply reviewed import</button>`;window.finReviewed={rows,kind:finImportKind,hash:finImportHash};}
function finDownload(data,name){const url=URL.createObjectURL(new Blob([data],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function finRestore(file){if(!file)return;if(file.size>10*1024*1024)throw Error('Backup exceeds 10 MB');const incoming=F.validate(JSON.parse(await file.text()));if(!confirm(`Restore this Finance backup (${incoming.debts.length} debts, ${incoming.events.length} debt events, ${incoming.paydays.length} paycheques, ${incoming.payUses?.length||0} actions, ${incoming.goals?.length||0} savings goals)? This replaces Finance only. Download a current backup first.`))return;const previous=localStorage.getItem(FIN_KEY),wasBlocked=finBlocked,wasStored=finStoredRaw;if(previous)finDownload(previous,'finance-before-restore-'+finToday()+'.json');finBlocked=false;finStoredRaw=previous;try{finCommit(incoming);}catch(e){finBlocked=wasBlocked;finStoredRaw=wasStored;throw e;}}
function finPayday(form){const data=Object.fromEntries(new FormData(form)),source=F.incomeSources(finState).find(x=>x.id===data.sourceId&&x.active);if(!source)throw Error('Add and choose an income source first');if(data.date>finToday())throw Error('Actual pay cannot be future-dated');const amount=F.money(data.amount),existing=finState.paydays.find(p=>(p.sourceId||'legacy')===source.id&&p.date===data.date),id=existing?.id||'preview-pay',receipt={id,sourceId:source.id,sourceName:source.name,date:data.date,amount,...(data.through?{through:data.through}:{})},staged={...finState,paydays:[...finState.paydays.filter(p=>p.id!==id),receipt]};if(F.paycheckRemaining(staged,id)<0)throw Error('This is less than already assigned from the recorded paycheque');const plan=F.paycheckPlan(staged,id,finToday()),recorded=finState.paydays.filter(p=>p.date===data.date&&(p.sourceId||'legacy')!==source.id).reduce((n,p)=>n+p.amount,0);finPlan={amount,date:data.date,sourceId:source.id,plan};document.getElementById('fin-plan').innerHTML=`<div class="card"><h3>Household plan until ${plan.end}</h3><p class="fin-note">${esc(source.name)}: ${finMoney(amount)}${recorded?' + '+finMoney(recorded)+' already recorded on this date':''}. Uses unassigned actual pay only. Expected future income is excluded. Recommendations are not completed actions.</p>${plan.rows.filter(r=>r.allocated>0).map(r=>`<div class="fin-row"><span>${esc(r.name)}<br><small>${r.due} · ${r.kind}</small></span><strong>${finMoney(r.allocated)}</strong></div>`).join('')}<p class="fin-note ${plan.shortfall?'fin-danger':''}">${plan.shortfall?'Required-obligation shortfall: '+finMoney(plan.shortfall):'Unassigned household buffer: '+finMoney(plan.left)}</p>${plan.deadlineShortfall?'<p class="fin-note fin-danger">Deadline-pace gap: '+finMoney(plan.deadlineShortfall)+'</p>':''}<button class="btn btn-primary" data-fin="save-pay">Save actual take-home pay</button><p class="fin-note">After saving, record what you actually did against this paycheque. This does not make bank payments.</p></div>`;}

let finPrivateSetup=null;
async function finPickSetup(file){
 if(!file)return;if(file.size>1024*1024)throw Error('Setup exceeds 1 MB');finPrivateSetup=null;document.getElementById('fin-setup-review').innerHTML='';const setup=JSON.parse(await file.text());
 if(setup.type!=='life-hub-finance-setup'||setup.version!==1||!Array.isArray(setup.sources)||setup.sources.length>30||!Array.isArray(setup.accounts)||setup.accounts.length>30)throw Error('Invalid private Finance setup');
 const sources=F.incomeSources(finState),options=(items,name)=>'<option value="skip">Skip this item</option>'+items.map(x=>`<option value="${esc(x.id)}" ${F.key(x.name)===F.key(name)?'selected':''}>Update ${esc(x.name)}</option>`).join('');
 const sourceRows=setup.sources.map((x,i)=>{F.validate({...F.empty(),incomeSources:[{...x,expected:x.expected??0,active:true}]});return `<label for="fin-setup-source-${i}">${esc(x.name)}</label><select class="inp" id="fin-setup-source-${i}" data-setup-source="${i}"><option value="new" ${sources.some(s=>F.key(s.name)===F.key(x.name))?'':'selected'}>Add as a new source</option>${options(sources,x.name)}</select><p class="fin-note">Next dates: ${F.upcomingPaydays({...F.empty(),incomeSources:[{...x,active:true}]},finToday(),3).map(p=>finDisplayDate(p.date)).join(' · ')}</p>`;}).join('');
 const accountRows=setup.accounts.map((x,i)=>{if(typeof x.name!=='string'||!Array.isArray(x.deadlines)||x.deadlines.length>30)throw Error('Invalid payoff milestones');const temp={id:'preview',name:'Preview',opening:1e12,payment:0,apr:0,frequency:'monthly',nextDue:finToday(),asOf:finToday(),deadlines:x.deadlines,deadlineAsOf:finToday(),deadlinePaymentIds:[]};F.validate({...F.empty(),debts:[temp]});return `<label for="fin-setup-account-${i}">${esc(x.name)} milestones · choose its existing debt</label><select class="inp" id="fin-setup-account-${i}" data-setup-account="${i}">${options(finState.debts,x.name)}</select><div class="fin-scroll">${x.deadlines.map(d=>`<div class="fin-row"><span>${esc(d.label)}<br>${finDisplayDate(d.due)}</span><strong>${finMoney(d.amount)}</strong></div>`).join('')}</div>`;}).join('');
 finPrivateSetup=setup;document.getElementById('fin-setup-review').innerHTML=`<h3>Review private setup</h3><p class="fin-note">Match an existing source to update its rule while keeping its pay history. Otherwise add a new source. Unselected sources remain active, so pause obsolete schedules if needed. No expected amount replaces an existing amount unless provided in the file.</p>${setup.calendarPay?'<p class="fin-note">Includes a private work-calendar snapshot linked to the selected income source. Dollar estimates require confirmed payroll assumptions in Calendar-based pay estimates.</p>':''}${sourceRows}${finField('setup-asOf','Milestone balance snapshot date · confirm when photos were current','date',finToday(),`required max="${finToday()}"`)}${accountRows}<p class="fin-note">Applying replaces only the selected debts’ milestone lists. It keeps actual balances, payments, reconciliations, budgets and scenarios. Promotion amounts are portions of an account; no debts or transactions are added. Photos do not establish APR, deferred-interest charges or lender payment allocation. Confirm those in your statement.</p><button class="btn btn-primary" data-fin="setup-apply">Apply reviewed setup</button>`;
}
function finApplySetup(){
 if(!finPrivateSetup)throw Error('Choose a private setup file first');const on=document.getElementById('fin-setup-asOf').value;if(on>finToday())throw Error('Snapshot date cannot be future-dated');
 const mapping={sources:Array.from(document.querySelectorAll('[data-setup-source]'),x=>x.value),accounts:Array.from(document.querySelectorAll('[data-setup-account]'),x=>x.value)};
 finCommit(F.mergeSetup(finState,finPrivateSetup,mapping,on));finPrivateSetup=null;document.getElementById('fin-setup-review').innerHTML='';
}

function finRenderCfo(){
 const host=document.getElementById('fin-cfo');if(!host)return;const open=document.getElementById('fin-cfo-section')?.open,brief=F.cfoBrief(finState,finToday());
 const actionLabel={paydays:'Review paydays',budget:'Review budget',debt:'Set payment',reconcile:'Confirm balance',milestones:'Review milestones'};
 const formatSigned=n=>(n<0?'−':'')+finMoney(Math.abs(n));
 host.innerHTML=`<details class="card" id="fin-cfo-section" ${open?'open':''}><summary>CFO check-in · ${brief.issues.length?brief.issues.length+' items to review':brief.reviewDue?'weekly review due':'reviewed this week'}</summary><p class="fin-note">Your next 30 days · ${brief.on} through ${F.add(brief.end,-1)}. Expected income and budget schedules are plans, not confirmed bank cash or a safe-to-spend figure.</p><div class="fin-grid"><div><span class="fin-badge">Expected income</span><h2>${finMoney(brief.knownIncome)}</h2></div><div><span class="fin-badge">Scheduled obligations</span><h2>${finMoney(brief.scheduledOut)}</h2></div></div><p class="fin-note">${brief.complete?'Planned income less scheduled obligations: '+formatSigned(brief.plannedDifference)+'.':'Planned difference unavailable: add income amounts, schedules and living costs first.'} Credit balances, cash on hand, unrecorded spending and overdue bills are not included. Milestones are debt portions and are not added again to these totals.</p><h3>Needs your attention</h3>${brief.issues.length?brief.issues.map(x=>`<div class="fin-row"><p class="fin-note">${esc(x.text)}</p><button type="button" class="btn btn-ghost" data-fin="cfo-action" data-action="${x.action}" data-id="${esc(x.debtId||'')}">${actionLabel[x.action]}</button></div>`).join(''):'<p class="fin-note">No setup or deadline warnings from the records entered. Review bank cash, actual spending and lender statements before making decisions.</p>'}<details><summary>Income & obligations calendar</summary><div class="fin-scroll">${[...brief.income.map(p=>({...p,kind:'expected income',amount:p.expected})),...brief.obligations].sort((a,b)=>a.date.localeCompare(b.date)).map(x=>`<div class="fin-row"><span>${esc(x.name)}<br><small>${x.date} · ${x.kind}</small></span><strong>${x.amount?finMoney(x.amount):'Amount needed'}</strong></div>`).join('')||'<p class="fin-note">Add your schedules to see upcoming dates.</p>'}</div><p class="fin-note">Budget entries are reservations, not confirmed paid bills. Actual received pay is removed from upcoming income; completed debt payments reduce matching scheduled obligations.</p></details><details><summary>Payoff deadlines ahead</summary>${brief.deadlines.map(x=>`<div class="fin-row"><span>${esc(x.debtName)} · ${esc(x.label)}<br><small>${x.due}</small></span><strong>${finMoney(x.remaining)}</strong></div>`).join('')||'<p class="fin-note">No dated payoff milestones entered.</p>'}</details><h3>Weekly household review</h3><p class="fin-note">Confirm bank cash and statements, record payments, check upcoming bills and pay, then review your next focus and What If decisions.</p><label for="fin-review-note">Review note · optional</label><textarea class="inp" id="fin-review-note" maxlength="1000" rows="2" placeholder="Decisions or follow-ups for next week">${esc(finState.cfoReview?.note||'')}</textarea><button class="btn btn-primary" data-fin="cfo-reviewed">Mark household review complete</button><p class="fin-note">${finState.cfoReview?'Last review: '+finState.cfoReview.date:'No weekly review recorded yet.'} Marking reviewed never confirms balances or records payments.</p></details>`;
}
function finCfoAction(action,id){
 if(action==='reconcile')return finEditor('reconcile',id);if(action==='debt')return finEditor('edit',id);if(action==='milestones')return finEditor('deadlines',id);
 const target=action==='paydays'?document.getElementById('fin-household-paydays'):document.getElementById('fin-budget').closest('details');target.open=true;target.scrollIntoView({block:'start',behavior:'smooth'});
}

function finInit(){finLoad();const page=document.getElementById('page-finance');page.innerHTML=`<div class="page-title">Finance</div><p class="fin-note">A clear plan for your next payday.</p><div id="fin-status" role="status" aria-live="polite"></div><div id="fin-dashboard"></div><div id="fin-pay-quick"></div><div id="fin-progress"></div><div id="fin-paychecks"></div><div id="fin-voice"></div><div id="fin-decisions"></div><div id="fin-cfo"></div><div id="fin-calendar"></div><div id="fin-editor"></div><details class="card" id="fin-household-paydays"><summary>Household paydays · record pay & manage schedules</summary><p class="fin-note" id="fin-pay-schedule"></p><div id="fin-income-sources"></div><details><summary>Upcoming income</summary><div id="fin-upcoming-income"></div></details><div class="fin-actions"><button class="btn btn-ghost" data-fin="schedule">Set payday schedule</button></div><details><summary>Import a private schedule & payoff setup</summary><p class="fin-note">Load a prepared setup file privately on this device, then review how it matches your existing income sources and debts.</p><label for="fin-setup-file">Private Finance setup (.json)</label><input id="fin-setup-file" type="file" accept=".json"><div id="fin-setup-review"></div></details><form id="fin-pay-form"><label for="fin-pay-source">Income source</label><select class="inp" id="fin-pay-source" name="sourceId"></select>${finField('pay-amount','Actual take-home pay','number','','required min="0" step="0.01" inputmode="decimal"').replace('name="pay-amount"','name="amount"')}${finField('pay-date','Pay date','date',finToday(),`required max="${finToday()}"`).replace('name="pay-date"','name="date"')}<details><summary>Adjust planning period</summary>${finField('pay-until','Plan up to this date · optional','date','','').replace('name="pay-until"','name="through"')}<p class="fin-note">Leave blank to plan until the next household payday from any active source.</p></details><button class="btn btn-primary">Plan this pay</button></form></details><div id="fin-plan"></div><details class="card"><summary>Budget & upcoming obligations</summary><button class="btn btn-ghost" data-fin="bill">Add budget category</button><div id="fin-budget"></div></details><details class="card"><summary>Payment & statement history</summary><div id="fin-history"></div></details><details class="card"><summary>Import Excel workbook</summary><p class="fin-note">Your workbook stays on this device. Choose a worksheet, map columns and review before saving. Importing updates settings, never payment history.</p><label for="fin-workbook">Budget workbook (.xlsx)</label><input id="fin-workbook" type="file" accept=".xlsx"><div id="fin-import"></div></details><details class="card"><summary>Backup & restore</summary><p class="fin-note">Finance saves in this browser on this device. It does not sync across devices or browsers. Clearing site data removes it. Download backups regularly; they contain private financial information in plain text. Restore a backup on another device to transfer it.</p><button class="btn btn-ghost" data-fin="backup">Download Finance backup</button><label for="fin-restore">Restore Finance JSON backup</label><input id="fin-restore" type="file" accept=".json"></details><p class="fin-note">Estimates use daily simple interest (APR ÷ 365), rounded at each recorded event and payment date. Actual lender compounding, fees and rate changes may differ. Forecasts assume scheduled payments continue; no new borrowing or fees. Confirm balances using lender statements. Currency: CAD.</p>`;
 page.addEventListener('click',async e=>{const b=e.target.closest('[data-fin]');if(!b)return;const a=b.dataset.fin;try{if(['add','edit','payment','reconcile','bill','bill-edit','schedule','deadlines'].includes(a))finEditor(a,b.dataset.id);if(a==='goal-assign'){const pay=finState.paydays.find(p=>F.paycheckRemaining(finState,p.id)>0);if(!pay){document.getElementById('fin-household-paydays').open=true;document.getElementById('fin-pay-form').scrollIntoView({block:'start',behavior:'smooth'});finMessage('Enter actual pay before assigning a contribution.');}else{finSelectedPayId=pay.id;finPaycheckRender();finPayUseEditor({kind:'goal',id:b.dataset.id,allocated:Math.max(0,finState.goals.find(g=>g.id===b.dataset.id).target-F.goalBalance(finState,b.dataset.id,finToday()))});}}if(a==='paycheck-new'){const target=document.getElementById('fin-household-paydays');target.open=true;document.getElementById('fin-pay-form').scrollIntoView({block:'start',behavior:'smooth'});document.getElementById('fin-pay-amount').focus();}if(a==='decision-jump')document.getElementById('fin-decision-check').scrollIntoView({block:'start',behavior:'smooth'});if(a==='cfo-action')finCfoAction(b.dataset.action,b.dataset.id);if(a==='cfo-reviewed')finCommit({...finState,cfoReview:{date:finToday(),note:document.getElementById('fin-review-note').value}});if(a==='open-import'){const detail=document.getElementById('fin-workbook').closest('details');detail.open=true;detail.scrollIntoView({block:'start',behavior:'smooth'});}if(a==='setup-apply')finApplySetup();if(a==='deadline-row')document.getElementById('fin-deadline-rows').insertAdjacentHTML('beforeend',finDeadlineRow());if(a==='schedule-date'){const host=document.getElementById(b.dataset.kind==='holiday'?'fin-holiday-dates':'fin-date-overrides');host.insertAdjacentHTML('beforeend',b.dataset.kind==='holiday'?finHolidayRow(''):finOverrideRow({scheduled:'',actual:''}));host.querySelector('label:last-child input')?.focus();}if(a==='income-toggle'){const sources=F.incomeSources(finState).map(x=>x.id===b.dataset.id?{...x,active:!x.active}:x);finCommit({...finState,incomeSources:sources});}if(a==='cancel')document.getElementById('fin-editor').innerHTML='';if(a==='template-preview')await finTemplatePreview();if(a==='template-apply')finTemplateApply();if(a==='strategy')finCommit({...finState,strategy:finState.strategy==='snowball'?'avalanche':'snowball'});if(a==='map')finMap();if(a==='preview')await finPreview();if(a==='apply'){if(!window.finReviewed)throw Error('Preview the import first');const r=window.finReviewed;finCommit(F.merge(finState,r.rows,r.kind,r.hash,finToday()));document.getElementById('fin-import').innerHTML='';window.finReviewed=null;}if(a==='backup')finDownload(finBlocked?(localStorage.getItem(FIN_KEY)||'{}'):JSON.stringify(finState,null,2),'life-hub-finance-'+finToday()+'.json');if(a==='save-pay'){if(!finPlan)throw Error('Plan your pay first');const id=finId();const next=F.recordPay(finState,{id,date:finPlan.date,amount:finPlan.amount,sourceId:finPlan.sourceId,through:finPlan.plan.end});finSelectedPayId=id;finCommit(next);document.getElementById('fin-pay-amount').value='';document.getElementById('fin-paycheck-section').scrollIntoView({block:'start',behavior:'smooth'});}}catch(err){finMessage(err.message,true);}});
 page.addEventListener('submit',e=>{e.preventDefault();try{if(e.target.id==='fin-edit-form')finSaveEditor(e.target);if(e.target.id==='fin-pay-form')finPayday(e.target);}catch(err){finMessage(err.message,true);}});
 page.addEventListener('change',async e=>{try{if(e.target.closest('#fin-edit-form[data-action="schedule"]'))finSchedulePreview();if(e.target.id==='fin-focus-choice')finCommit({...finState,focusDebtId:e.target.value});if(e.target.closest('#fin-pay-form')){finPlan=null;document.getElementById('fin-plan').innerHTML='';}if(e.target.id==='fin-setup-file')await finPickSetup(e.target.files[0]);if(e.target.id==='fin-workbook')await finPickWorkbook(e.target.files[0]);if(e.target.id==='fin-restore')await finRestore(e.target.files[0]);if(e.target.closest('#fin-import')){window.finReviewed=null;finTemplateReviewed=null;const templatePreview=document.getElementById('fin-template-preview');if(templatePreview)templatePreview.innerHTML='';const preview=document.getElementById('fin-preview');if(preview)preview.innerHTML='';}}catch(err){finMessage(err.message,true);}});finRender();
}
finInit();
